import javax.imageio.ImageIO;import java.awt.image.BufferedImage;import java.io.File;
public class AtlasBounds {public static void main(String[] args)throws Exception{BufferedImage b=ImageIO.read(new File(args[0]));System.out.println("atlas="+b.getWidth()+"x"+b.getHeight());for(int i=0;i<6;i++){int left=i%3*b.getWidth()/3,right=(i%3+1)*b.getWidth()/3,top=i/3*b.getHeight()/2,bottom=(i/3+1)*b.getHeight()/2;int l=right,r=left,t=bottom,bt=top;for(int y=top;y<bottom;y++)for(int x=left;x<right;x++)if((b.getRGB(x,y)>>>24)>60){l=Math.min(l,x);r=Math.max(r,x);t=Math.min(t,y);bt=Math.max(bt,y);}System.out.printf(java.util.Locale.US,"{%.6ff,%.6ff,%.6ff,%.6ff},%n",(float)l/b.getWidth(),(float)t/b.getHeight(),(float)(r-l+1)/b.getWidth(),(float)(bt-t+1)/b.getHeight());}}}
